// Compares the PTSA answer scripts generated by src/ptsa.js with the scripts on the source page
// and tests the command checker on abbreviated input.
// Usage: node scripts/check-lab.mjs page.html
import fs from 'fs';
import { dec } from './parse.mjs';
import { SCENARIOS, steps, showLine, checkStep, addressing, prefixFor } from '../src/ptsa.js';

const page = fs.readFileSync(process.argv[2], 'utf8');
const scripts = [...page.matchAll(/<pre class="code_answer"[^>]*>([\s\S]*?)<\/pre>/g)].map((m) => dec(m[1]));
const commands = (text) =>
  text.split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('!') && l !== 'exit');
let failed = 0;
const fail = (msg) => (failed++, console.log('FAIL', msg));

for (const s of SCENARIOS) {
  for (const device of [s.router, s.switch]) {
    const src = scripts.find((t) => t.includes(`ID ${s.id}`) && new RegExp(`SCRIPT FOR (ROUTER|SWITCH) ${device}\n`).test(t + '\n'));
    if (!src) { fail(`no source script for ${s.id} ${device}`); continue; }
    const want = commands(src);
    const list = steps(s).filter((st) => st.device === device);
    const got = list.flatMap((st) => st.lines.map(showLine));
    if (JSON.stringify(want) !== JSON.stringify(got)) {
      fail(`${s.id} ${device}`);
      want.forEach((l, i) => l !== got[i] && console.log('  source:', l, '\n  ours:  ', got[i]));
    }
    // every step accepts the source commands
    let i = 0;
    for (const st of list) {
      const text = want.slice(i, i + st.lines.length).join('\n');
      i += st.lines.length;
      if (!checkStep(st, text).ok) fail(`${s.id} ${device}: source rejected for "${st.task}"`);
    }
  }
  const a = addressing(s);
  console.log(`${s.id}: LAN1 ${a.lan1.network}/${a.lan1.prefix}, LAN2 ${a.lan2.network}/${a.lan2.prefix}, ${s.pcA} ${a.pcA}, ${s.pcB} ${a.pcB}`);
}

// abbreviated answers that must be accepted
const s = SCENARIOS[0];
const st = steps(s);
const accept = [
  ['Przejdź', 'en\nconf t'],
  ['G0/0/0', 'int g0/0/0\ndesc LAN 2\nip add 192.168.10.129 255.255.255.192\nno shut'],
  ['RSA', 'crypto key gen rsa gen mod 1024'],
  ['Wyłącz wyszukiwanie', 'no ip domain lookup'],
  ['nieużywane', 'int range f0/1-4,f0/7-24,g0/1-2\ndesc unused\nshut'],
  ['nieużywane', 'interface range gi0/1 - 2, fa0/7 - 24, fa0/1 - 4\ndescription Unused\nshutdown\nexit'],
  ['zapisz', 'end\nwr'],
  ['Linie vty', 'line vty 0 15\nlogin local\ntransport input ssh\nexit'],
  ['baner', 'banner motd $Authorized access only$'],
  ['minimalną', 'sec pass min 10'],
];
for (const [key, text] of accept) {
  const step = st.find((x) => x.task.includes(key));
  if (!checkStep(step, text).ok) fail(`should accept "${text}" for "${step.task}"`);
}
const reject = [
  ['Ustaw zaszyfrowane', 'enable secret donttellanyone'],
  ['nieużywane', 'int range f0/1-24\ndesc unused\nshut'],
  ['G0/0/0', 'int g0/0/0\ndesc LAN 2\nip add 192.168.10.129 255.255.255.128\nno shut'],
];
for (const [key, text] of reject) {
  const step = st.find((x) => x.task.includes(key));
  if (checkStep(step, text).ok) fail(`should reject "${text}"`);
}
if (prefixFor(100) !== 25 || prefixFor(62) !== 26 || prefixFor(63) !== 25) fail('prefixFor');
console.log(failed ? `${failed} failed` : 'all OK');
process.exit(failed ? 1 : 0);
